insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 1, 'Five identical devices, each cutting at 9 micron, are put in series on the OGBOTOBO inlet water. The first removes 65.398946 percent and the fifth removes 12.284239 percent. What is that fall a measurement of?', '["The cut size tightening along the train, because each stage is sized against the water arriving at it rather than against the inlet of the plant.", "What the four stages upstream of it left behind, since every device in that column is the same device on the same geometry.", "The grade curve flattening as the sharpness falls from 3 at the head of the train to 2 at the tail of it.", "The concentration falling below the level at which this module will still report a stage removal for a device at all."]'::jsonb, 1, 'The engine prints each stage removal as a fraction of the first stage''s: 1.000000, then 0.486641, then 0.313934, then 0.233950, then 0.187835. Nothing about the equipment moves down that column. The water does.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 2, 'Compounding a 65.398946 percent removal five times over predicts 8.927280 ppm where the train reports 250.692079 ppm. Which assumption does the compounding make that this engine does not?', '["That the five devices are identical, where the engine sizes each stage against the water reaching it and so gives the five of them five different cut sizes.", "That the volume surviving in one size bin is a product across the devices, which holds only while the stages are taken in the order they were designed in.", "That the oil being removed is homogeneous, so a device takes a fixed fraction of the whole rather than a fixed fraction of each droplet size.", "That the outlet comes back on the basis the inlet was given on, where the compounded figure is by mass and the train figure is by volume."]'::jsonb, 2, 'The volume surviving in one size bin does compound exactly. The removal over the whole distribution does not, because the weight shifts towards the fine end at every stage and the fine end is where the grade efficiency is low.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 3, 'The four OGBOTOBO devices are run as designed and then run in reverse. Which figures are left where they were and which move?', '["The outlet of 160.391597 ppm and the outlet median of 3.185598 micron are unchanged, and every stage removal moves.", "The stage removals are unchanged and the outlet moves, because the device at the end of a train sets the concentration leaving it.", "Both the outlet and the stage removals are unchanged, because a product of survivals is being taken and nothing on the return is position dependent.", "The outlet median is unchanged and the outlet concentration moves by 7.09e-16 ppm, which is the float rounding the module reports beside it."]'::jsonb, 0, 'Reversed, the four stages read 60.582215, 48.170414, 56.381625 and 0.006985 percent, and the per stage figures move by as much as 57.344778 percentage points. The two outlet figures agree to 7.09e-16 relative.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 4, 'Why does reordering the stages of a train leave its outlet exactly where it was?', '["Because the bin set is renormalised after every stage, so the distribution arriving at the last device is the same one whichever route it took through the plant.", "Because the coarse device removes so little on this water, 3.237437 percent, that moving it cannot change what the other three stages do.", "Because both medians are interpolated across the bin they fall in, which removes the grid steps that would otherwise make the arrangement visible.", "Because a device removes a fixed fraction of each droplet SIZE, so the volume surviving in any one size bin is the product of the survivals across the devices, and a product does not care what order it is taken in."]'::jsonb, 3, 'It is a statement about multiplication. It needs no data, no calibration and no published case, which is exactly what makes it a good check on the coupling.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 5, 'A designer reads the order identity and concludes that the arrangement of the plant is free to choose. What has that reading missed?', '["That the identity holds only while every stage runs, so a skipped vessel makes the outlet depend on position after all.", "Fouling, plugging and how much oil each device can take in its reject are what decide the arrangement, and this module carries none of them.", "That the identity was measured on one train of four stages and is not claimed for trains longer than that.", "That the stage removals change, and the overall removal of 91.089356 percent changes with them."]'::jsonb, 1, 'An invariance in a model is a statement about the model. It says what the model is insensitive to, and everything left out of the model is also something the invariance cannot see.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 6, 'The walnut shell filter reports 14.382082 percent in the OGBOTOBO train as designed and 60.582215 percent when the same four devices are reversed. What changed?', '["The water reaching it. Nothing about the bed moved at all.", "Its cut size, which this engine re-sizes at each position from the concentration arriving at that position.", "Its sharpness, which is 2 where the bed follows an interception device and 3 where the bed leads the train.", "The basis of the figure, which is a fraction of the oil in the designed order and a fraction of the train inlet in the reversed one."]'::jsonb, 0, 'A stage removal is a property of a device and a water together. In a train the water is whatever the stages before it chose to leave, so the same bed honestly reports two very different percentages.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 7, 'In the four stage OGBOTOBO table the removals read 3.237437, 85.209861, 27.278164 and 14.382082 percent, and the outlets read 1741.726140, 257.603712, 187.334148 and 160.391597 ppm. Which of the two columns follows one quantity through the plant?', '["The removal column, because every figure in it is a fraction of the same train inlet of 1800 ppm.", "Both of them, because each removal on a row is that row''s outlet taken against the inlet of the train.", "The outlet column. The removal column is four numbers about four different waters.", "Neither of them, because both are reported per stage and only the droplet median carries one quantity from the inlet to the outlet."]'::jsonb, 2, 'Read the outlet column when you want the state of the water, and read the removal column only with the outlet of the row above it in hand.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 8, 'What does this engine state on every train return about the basis of the removal and the outlet concentration?', '["That the removal is a fraction of the oil and the outlet is converted to mg per litre, which is the basis a discharge comparison has to be made on.", "That both are on a volume basis, because the distribution is log-normal in droplet volume and the quadrature is taken over volume bins.", "That the removal is a fraction of the whole stream while the outlet is a fraction of the oil, which is why the two can never be multiplied together.", "That the removal is a fraction of the OIL and so dimensionless, and that the outlet comes back on whatever basis the inlet was given on, ppm by mass in giving ppm by mass out."]'::jsonb, 3, 'It adds that comparing the result with a figure written in mg/l is a conversion the caller must make, and that this module states no limit of its own.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 9, 'Eight identical devices, each cutting at 4 micron, are put on the wide OGBOTOBO inlet at sigma 0.95. What is left?', '["Nothing a median can be read off, the surviving volume being dust.", "36.154977 ppm, with the droplet median down at 1.700800 micron.", "2.364977 ppm, the figure a 2 micron device reaches.", "160.391597 ppm, because the fine tail beats more equipment and no train does better than the four stage one on this water."]'::jsonb, 1, 'The fine tail of a wide distribution carries volume that no device in this module removes at all. The devices are working and the thing they are working on has receded below them.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 10, 'A narrow inlet of 650 ppm at d50 26 micron and sigma 0.7 through one device cutting at 2 micron reports a dispersed figure of 2.364977 ppm, a reported outlet of 5.000000 ppm and floorApplied yes. Whose number is the 5 ppm?', '["The module''s own floor, which sits in the frozen constants and is applied whenever a dispersed prediction falls under it.", "This engine''s estimate of the dissolved oil in that water, derived from the salinity and the temperature of the stream.", "The caller''s. No value for the dissolved and soluble oil floor is stated anywhere in this module.", "A specification, which the module reports the higher of."]'::jsonb, 2, 'Both figures are on the return, so a reader can see which is which, and the warning that arrives with it names the caller as the source of the floor.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 11, 'On the wide inlet eight devices still leave 36.154977 ppm, and on the narrow inlet one device takes the dispersed oil to 2.364977 ppm. What decides which of those two limits a design is up against?', '["The number of stages, since a train of eight can never reach a floor that one device reaches in a single pass.", "The cut size, since any device cutting below 4 micron reaches the floor and any device above it is held up by the tail.", "The specification given, since the module compares against it and reports whichever of the two limits binds first in the margin field.", "The inlet distribution. A wide spread holds the answer up on its fine tail, and a narrow one dives under a floor this model cannot see unless a caller states it."]'::jsonb, 3, 'The two limits call for completely different responses. Against the tail you change the inlet. Against the floor you stop, because no equipment in this module addresses dissolved oil at all.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 12, 'The published train cases print a golden outlet of 6.388448 ppm beside an engine outlet of 6.366280 ppm on the Suite''s own shipped default train. Where does the golden figure come from?', '["Particle tracking: 400000 droplets, each carrying a surviving weight through every stage, with no binning anywhere.", "The engine''s own answer recorded back at an earlier release, which is why the two figures are close without being equal.", "The same quadrature over the same 60 bin grid, re-run at a tighter convergence tolerance than the engine uses.", "A published field measurement on that shipped train, which is the one case in this file with plant data behind it."]'::jsonb, 0, 'That route has no bins in it at all, so it validates the quadrature, the coupling, the outlet concentration, every stage and both medians at once.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 13, 'The API 421 basin removes 3.237437 percent of the oil at the head of the OGBOTOBO train and 0.006985 percent at the tail of the reversed one. Which of the two readings of that basin is right?', '["The 3.237437 percent, since a device is rated on its design inlet.", "Both. A stage removal is a fact about a device and a water together, and those are two different waters.", "The 0.006985 percent, since it is the worst the basin can do.", "Neither, because a basin whose cut of 112.300216 micron sits above every droplet in this water cannot be given a removal at all."]'::jsonb, 1, 'Quoted alone, either figure is an anecdote. Quoted with the outlet median of the stage before it, either one is a measurement.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 14, 'The OGBOTOBO train reports 91.089356 percent overall against stage removals of 3.237437, 85.209861, 27.278164 and 14.382082 percent. What is the overall figure taken over?', '["The stages that ran, which here is the sum of the four.", "The largest stage removal, scaled by the stage count.", "Every stage in the train, from the inlet of 1800 ppm to the outlet of 160.391597 ppm.", "The dispersed oil alone, with the dissolved fraction taken off the inlet before the percentage is formed on the remainder."]'::jsonb, 2, 'The train reports 4 of 4 stages ran, complete yes and 0 stages skipped, so the overall figure covers the whole plant.'),
  ('producedwater', 'advanced', 'module', 'm01-the-coupling', 15, 'Beside its concentrations the OGBOTOBO train reports a grid of 60 bins over 4 sigma and a truncated tail of 0.000063372072. Why is the grid on the return at all?', '["Because the truncated tail has to be added back to the outlet concentration by the caller before the figure is quoted.", "Because the bin count is an output here, chosen from the sigma of the inlet so that the quadrature converges on this water.", "Because the truncated tail is the dissolved oil floor, which the module has no other way of stating.", "Because the grid moves the answer, so this module reports it back rather than hiding it as an implementation detail."]'::jsonb, 3, 'A reader can then read a median or a removal off the same object that says what grid it was computed on.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 1, 'A train hands a reader an inlet droplet median and an outlet one, knowing the reader will compare them. What does this engine guarantee about the pair, and where does it say so?', '["That the inlet figure is read straight from the analytic log-normal and the outlet figure off the bins afterwards, which is the reason the inlet reproduces the typed d50 so closely.", "That both are number medians rather than volume medians, so the comparison is unaffected by how volume is spread across the bins.", "That both are the volume median of the same bin set, interpolated across the bin the median falls in, and it says so in those words on every return.", "That both are bin midpoints on one grid, so the two are quantised identically and the difference between them is exact."]'::jsonb, 2, 'A declaration of BASIS is what makes a difference between two figures a measurement rather than a coincidence. A figure with a stated basis can be argued with.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 2, 'The OGBOTOBO inlet median comes back as 14.000000 micron against a typed d50 of 14, reproducing it to 1.19e-9 relative. What kind of agreement is that?', '["An identity. The volume median of a log-normal IS its own d50, so a bin set that fails to reproduce the typed figure has described the distribution wrongly.", "A validation against the golden file, whose published bin grid group carries that same figure at five different conditions.", "A convergence tolerance: the median is bisected out of the bin set, and 1.19e-9 is where the bisection is allowed to stop.", "A calibration, chosen so that an inlet median lands on the typed figure at the module''s own default grid of 60 bins."]'::jsonb, 0, 'The typed figure is kept beside the measured one on the return as `inletD50Micron`, so a reader can see both and can see that they agree.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 3, 'Across the cut size sweep the outlet median falls 9.006299, 7.097314, 5.720019, 4.371791, 3.237392 and 2.179329 micron. What would a flat run of three identical figures in that column have told you?', '["That the outlet concentration had stopped responding to the cut size over those three rows as well.", "That the median had been read as a bare bin midpoint, so it was quantised to the grid rather than interpolated across it.", "That the distribution had been truncated, so the volume beyond the span was being absorbed into the bin holding the median.", "That the sharpness had moved from 2 to 3 across those rows, which flattens the grade curve on either side of the cut."]'::jsonb, 1, 'A quantised median can only take as many values as there are bins, so it shows up as a flat run in a column that should be strictly falling.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 4, 'A jest test asserts that the outlet median falls monotonically as the cut tightens, rather than checking one median against a published value. What does the sweep buy that the spot check does not?', '["It checks the reported median against the analytic log-normal at all six of the conditions in the sweep instead of at a single one.", "It pins the six outlet concentrations printed beside the medians, so any change in the quadrature fails this same assertion as well.", "It is the only check in this module that needs no source, since every other assertion compares against the golden file.", "It tests the SHAPE of a whole column, which a median that is right at one condition and quantised everywhere else cannot pass."]'::jsonb, 3, 'Shape is a much harder thing to get right by accident than a value at a point. A median correct at one condition passes a spot check and fails this one.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 5, 'Interpolating in log diameter removes the step from a reported median. What does it NOT remove?', '["The truncated tail, which the interpolation absorbs into whichever bin the reported median happens to fall in.", "The floor of 10 bins on the grid, which this module applies after the interpolation has run rather than before it.", "The grid, which still decides where the bin edges fall and therefore what is being interpolated between.", "The quantisation of the outlet concentration, which on this route is still read off the single bin holding the median."]'::jsonb, 2, 'A distribution described on 60 bins is a description rather than the distribution itself. Interpolation removes the step and leaves the instrument where it was.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 6, 'In the published bin grid cases the median column reads 30.000000, 30.000000, 12.000000, 30.000000 and 30.000000 against stated d50 figures of 30, 30, 12, 30 and 30, at bin counts from 30 to 240 and spans from 4 to 6. What does holding that across the whole group establish?', '["That the grid describes the distribution rather than distorting it, because the identity survives both knobs being moved.", "That the bin count and the span are outputs of this module rather than inputs a caller supplies, given that neither of the two moved the median anywhere in the group.", "That the median must be interpolated, since a quantised median could never land on a whole number.", "That 60 bins over 4 sigma is the only grid on which this module will describe a distribution."]'::jsonb, 0, 'A group that moved one knob could not say this. The identity is asserted across both of them at once.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 7, 'In the same published group the truncated tail reads 0.000063342484 at a span of 4, 0.000000573303 at a span of 5 and 0.000000001973 at a span of 6, and it is the same figure at 30 bins as at 60. Which knob moves it?', '["The bin count, because the tail is the volume sitting in the outermost bins and there are a great many more of those at 240 bins than at 30.", "The span, because it decides where the grid stops and therefore how much of the analytic distribution is left outside it.", "Both of them, because the tail is the volume that the normalisation absorbs and the normalisation itself runs across every bin in the set.", "Neither of them. Sigma alone sets the tail, which is why the published row at sigma 0.9 carries a different figure from the rows at 0.7."]'::jsonb, 1, 'Slicing the covered range more finely does nothing about what lies beyond it. Two knobs, and only one of them touches this quantity.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 8, 'A caller wants a finer answer out of the quadrature and a colleague wants more of the extremes of the distribution covered. Which knob does each of them reach for?', '["Both reach for the span, since a wider span at a fixed bin count also narrows the bins.", "Both reach for the bin count, since the grid reaches a fixed number of sigma either side of the median whatever the count.", "The bin count for the extremes and the span for the resolution, since the outermost bins are where the truncation happens.", "The bin count controls resolution inside the range the grid covers, and the span controls how far the grid reaches."]'::jsonb, 3, 'Resolution decides how finely volume is apportioned within the covered range, which is what the quadrature integrates against. Reach decides how much is covered at all.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 9, 'Why is a median read as a bare bin midpoint a coarse instrument on this grid?', '["Because the module reports the index of the bin the median falls in rather than a diameter, so the caller has to convert it.", "Each bin''s upper edge sits 13.503861 percent above its lower edge on the OGBOTOBO grid, so a midpoint median takes one value per bin and two outlets whose medians share a bin report the same one.", "Because the truncated tail sits in the outermost bins, so a midpoint read there is biased by the volume the normalisation absorbed.", "Because the median is taken before the outlet bins are normalised, so a midpoint is read against a surviving volume rather than against one."]'::jsonb, 1, 'Two trains with genuinely different outlets can come back with the same droplet median, which is exactly the comparison a reader is about to make.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 10, 'Across the cut sweep the outlet concentration falls from 1125.805910 ppm to 43.150877 ppm while the outlet median falls from 9.006299 to 2.179329 micron. What does each column tell a designer sizing a polishing stage?', '["The concentration says how hard the remaining oil is to remove, and the median says how much of it there is once the bins are weighted by volume.", "They say the same thing at two precisions, the median being the concentration read on the droplet grid.", "The concentration says how much oil is left, and the median says how hard the oil that is left will be to remove next.", "The concentration sizes the polishing stage, and the median says only whether the grid still resolves the distribution."]'::jsonb, 2, 'Both are consequences of the same tightening and neither is a substitute for the other. A designer sizing what comes next needs the second more than the first.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 11, 'The return carries the measured inlet median and the typed figure beside it as `inletD50Micron`. Why keep both?', '["Because the outlet median is compared against the typed figure rather than against the measured inlet one, so both of them have to be present on the return.", "Because the typed figure is what any verdict on the train is taken against in the case where no discharge specification has been given at all.", "Because a caller may pass a distribution with no d50 at all, in which case the measured figure is the only median on the return.", "They are different kinds of number, one typed and one measured off the bins, and carrying both lets a reader see that they agree."]'::jsonb, 3, 'The module checks itself against its own input and shows a reader the result, rather than reporting one figure and asking to be believed.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 12, 'Suppose this engine interpolated its medians correctly and said nothing about it on the return. What would a reader still be unable to do?', '["Know that an inlet median from one run and an outlet median from another are commensurable, which is what a stated basis settles.", "Compute the removal, since the removal is the ratio of the two medians.", "Reproduce either figure, since a median cannot be recovered from a bin set without the interpolation rule.", "Read the grid, since the bin count and the span are reported only alongside the basis string."]'::jsonb, 0, 'Every number would be right and the comparison would still be undefended. The basis strings say what each number is a number OF.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 13, 'The OGBOTOBO train takes the droplet median from 14.000000 to 3.185598 micron. What does that pair say about the oil still in the water?', '["It is 3.185598 micron across, so a device cutting anywhere below that size would take all of it out.", "It has fallen in the same proportion as the concentration, which runs from 1800 ppm to 160.391597 ppm.", "It is finer than the oil that has gone, so what is left is harder to remove than what has already been removed.", "It sits inside the fine tail the normalisation truncates, so the figure describes the grid rather than the water."]'::jsonb, 2, 'That is the sentence a designer needs in front of them before proposing another vessel.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 14, 'What grid does the OGBOTOBO train report beside its four stages, and what truncated tail does it carry on it?', '["60 bins over 4 sigma, with a truncated tail of 0.002699934563, which is the volume this grid leaves outside its span.", "60 bins over 4 sigma, with a truncated tail of 0.000063372072.", "240 bins over 6 sigma, with a truncated tail of 0.000000001973, which is the finest grid in the published cases.", "30 bins over 4 sigma, with a truncated tail of 0.000063342484, which is the figure the published grid cases carry."]'::jsonb, 1, 'Those are the module''s own defaults, and both of them are DECLARED values rather than derived ones.'),
  ('producedwater', 'advanced', 'module', 'm02-the-medians-and-the-grid', 15, 'The reported truncated tail is divided by twice the module''s own cdf at the lower span edge, and the answer comes out at 1.000000000000 at 30, 60, 120 and 600 bins. Why is that worth more than a comparison against a published figure?', '["Two parts of the module are asked the same question by different routes, so nothing outside the file is consulted and no tolerance has to be argued about.", "The ratio is taken at four bin counts, and four agreeing conditions outrank a single published condition.", "A tail measured on the bins is exact where a published tail has been rounded to six decimals first.", "The normalisation absorbs the tail, so the ratio is one by construction and cannot fail."]'::jsonb, 0, 'It says the tail the normalisation absorbs is exactly the analytic tail rather than a binning artefact. An engine agreeing with ITSELF, structurally, at every condition swept.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 1, 'A return carries real concentrations, a null meetsSpec, a null marginPpm and a reason string. Which of this module''s three acts is that?', '["A refusal, since a null field is how this module reports that it has no answer for the question it was asked.", "A withheld verdict. The train ran, and the pass or fail is the only thing missing from it.", "A warning, since the answer is reported in full and the reason string is the note that sits beside it.", "A failing train, since a verdict that is not reported is the module declining to say the train passed."]'::jsonb, 1, 'Withholding a verdict costs the reader nothing except the one thing the module has no basis for. The concentrations are still on the return.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 2, 'What does a refusal return in this module, and what does the module do about exceptions?', '["An object carrying a named error and nothing that could pass for an answer, and it throws nothing at all.", "An object carrying a named error beside whatever fields it could still compute, so a caller can use the partial result.", "A thrown exception naming the input, which is how a refusal is told apart from a withheld verdict on a train.", "A bare NaN, which the caller turns into a message, since only the leaves of this module carry error strings."]'::jsonb, 0, 'A thrown exception is a control flow event a caller can swallow. A returned object with an error key is data, and data survives being logged and displayed.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 3, 'One fluid whose oil is heavier than its water is put through this module. How many doors refuse it, and which are they?', '["Four, all of them devices, since the property functions accept any fluid and leave the check to the equipment.", "One, the rise velocity function, and the four devices then carry its error forward on their own returns.", "Five, four of them devices: the rise velocity function, and then the gravity separator, the plate pack, the hydrocyclone and the flotation cell.", "Five, one of them a device: four property functions refuse the fluid and the gravity separator refuses the cut."]'::jsonb, 2, 'Each refuses in its own words rather than through one shared sentence. A module where one export refuses a condition and another accepts it is holding two opinions about the same physics.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 4, 'logNormalCdf, gradeEfficiency and medianOfBins are called LEAVES. What do they do when they have no answer, and why that shape?', '["They return zero, which the callers above them test for and convert into a named refusal.", "They throw, because a helper with no error field has no other way of reporting an absence to its caller.", "They return an object with a named error, exactly like the other exports, which is why the census counts sixteen of them.", "They return a bare NaN, because each answers with a bare number and there is nowhere in the return to put an error key."]'::jsonb, 3, 'NaN poisons every arithmetic operation it touches and compares false against everything including itself, so it cannot be mistaken for a measurement.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 5, 'A device is applied at a cut size of zero, and the leaf underneath it produces a NaN. What reaches the caller?', '["An object with an error saying a device cannot be applied without a positive cut size and this one reports 0.", "The bare NaN, since the leaf detected the condition and the layer above it does not inspect the value it was handed.", "A cut size of zero carrying a warning that the grade efficiency is undefined at that cut.", "A removal of 100 percent, since every droplet in the distribution sits above a cut size of zero."]'::jsonb, 0, 'The leaf reports an absence in the only way it can, and the layer above it, which has somewhere to put a sentence, supplies the sentence.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 6, 'The error contract table in this course was not read off the source. How was it produced?', '["By listing the exports that carry an error key inside the module''s own frozen constants object.", "By calling every export twice, once with a question it can answer and once with a question it cannot, and recording both shapes.", "By running the jest suite and recording which of its assertions name an error string.", "By counting the refusals printed in the golden file, which carries one row for each refusing export."]'::jsonb, 1, 'Sixteen exports are callable. Thirteen carry the object contract and three are leaves.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 7, 'A three stage train is run with the plate area box cleared. What comes back?', '["A refusal naming the plate area and no concentrations at all, on the ground that a train is only ever as complete as the stages a caller managed to size.", "3 of 3 stages ran, with the plate pack contributing no removal and the verdict taken over the whole train.", "2 of 3 stages ran, complete no, skipped CPI plate pack, with 707.618822 ppm and 60.687843 percent still reported and no verdict at all.", "2 of 3 stages ran, with the verdict taken over the two that ran and a warning naming the third."]'::jsonb, 2, 'The reason is on the return in the engine''s own words: one stage did not run, so there is no train here to give a verdict on, and the concentrations are what the stages that DID run would leave.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 8, 'What does a stage that did not run carry on the return?', '["Its name, its cut size and a removal of zero, so that the list of stages keeps exactly the same shape on every single row a reader scans down.", "Its name and the concentrations that reached it, so a reader can see where in the plant the train stopped.", "Nothing. The stage is dropped from the list and the count of stages that ran is the only trace of it.", "Its name and its cause and nothing else, so a stage that is not there cannot show a confident process warning beside its own failure."]'::jsonb, 3, 'The skipped stage comes back as a name, a ran flag of false, and the error saying a plate pack needs a positive projected plate area in m2.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 9, 'A complete train is given a discharge specification of zero. What does the module report, and what distinction is it drawing?', '["meetsSpec null, with the reason that a specification must be a positive concentration and this is 0, which says the input is missing rather than the train failing.", "meetsSpec no, with a margin equal to the outlet, since no train at all can meet a specification of zero.", "meetsSpec null, with the reason that no discharge specification was given, which is the same branch as an empty box.", "A refusal naming the specification, since a figure that is not positive is an input this method cannot use."]'::jsonb, 0, 'A reader left with a blank reads it as a failing train. The module says which of the two it is instead.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 10, 'A run at sigma 1.5 reports a removal of 68.402514 percent, an outlet median of 5.944722 micron, and a warning that sigma is outside the customary band. What has the warning done to the answer?', '["It has suppressed the outlet median, so the figure printed beside the removal is the inlet one.", "Nothing. Both figures are the engine''s real answer at that input, and the warning is about the input.", "It has widened the grid to cover the extra spread, which is why the removal is lower than it is at sigma 1.", "It has withheld the verdict, since a run carrying a warning cannot be compared against a specification."]'::jsonb, 1, 'A warning names a quantity and a threshold, sits beside the answer and never changes what was returned. This one leaves you to decide whether your water is the exception.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 11, 'A liner bank past twice its design flow is refused. What is the module saying about that design?', '["That the bank is undersized and will miss its cut size, which is why the refusal names the liner count it wants.", "That the field has reached its ceiling, so the cut size would be the same figure at any higher flow.", "Nothing about the design. It is saying the question is outside what this method can answer, because the pressure drop and the inlet shear decide the answer there and this model does not carry them.", "That the shear penalty cannot be formed above twice design, so only the ideal cut is reported."]'::jsonb, 2, 'A refusal is not the engine saying the design is bad. The bank might be fine. The MODEL is not.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 12, 'Read the band edge refusals as a set: 200.5 C, 300001 ppm TDS, 100.1 API, and a brine density asked for at 100.5 C. What does each message carry?', '["The quantity and the nearest value inside the band, which the caller is then free to resubmit unchanged and unexamined.", "The quantity alone, the bands themselves being documented in the frozen constants object rather than repeated on each message.", "The quantity and the fitted correlation the band came from, so that a caller can extend it themselves.", "The quantity, the band it is stated to, and the value that fell outside it, so a reader knows which box to change."]'::jsonb, 3, 'Some of them add the reason as well. Past saturation a linear salinity correction has nothing behind it, and the refusal says so.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 13, 'A studio shows an empty verdict box beside real concentrations. What has it got wrong?', '["A reader reads a blank as a fail, so the screen has to show the REASON, and the three reasons say different things.", "Nothing at all, provided the concentrations printed beside it are right, since a blank is how the engine itself reports a withheld verdict.", "It should print the margin figure in place of the verdict, that field being null for a different reason from the verdict itself.", "It should fall back to the verdict from the last complete run, so that the box is never left empty."]'::jsonb, 0, 'A stage that did not run is a data entry problem, a missing specification is a question the user answers from their own permit, and a specification of zero is an input error.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 14, 'A train is handed null where an array of devices belongs. Which of the three acts is that, and what comes back?', '["A withheld verdict, since a train with no devices ran no stages and so has nothing to give a verdict on.", "A refusal: an object with an error saying the train needs an array of devices and it was given null.", "A warning beside an outlet equal to the inlet, since a train of no devices removes nothing from the water.", "A bare NaN, since the train is the caller that turns a leaf NaN into a name and no leaf ran here."]'::jsonb, 1, 'The input is one this method cannot use, so the return carries a named error and nothing that could pass for an answer.'),
  ('producedwater', 'advanced', 'module', 'm03-not-answering', 15, 'Before reading any number off a return, what should a reader sort it into?', '["One of the two shapes this module returns: an object of results, or else a bare NaN from whichever leaf was reached.", "One of the four kinds of return: a derived figure, a declared one, a calibrated one, or one held for literature.", "One of the three acts: an error string, a null verdict with a reason, or a full answer with a note beside it.", "One of the three warnings: the band edge one, the threshold one, or the one naming a quantity the caller supplied."]'::jsonb, 2, 'Each calls for a different sentence in a report, and only one of the three is a number that can be quoted at all.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 1, 'Stokes and the full drag balance are asked the same question at 5, 20, 60, 120, 240 and 500 micron in the UZERE water. What does the ratio between them do down that table?', '["It grows with the Reynolds number on every row, from 1.000088 at Reynolds 0.000020 to 1.785576 at Reynolds 19.883778.", "It holds at one across the rows inside the band and then jumps on the two rows outside it, which is where the module raises its warning.", "It falls as the droplet grows, because the full drag balance overtakes Stokes once the Reynolds number has passed one.", "It grows with the droplet diameter and is independent of the Reynolds number, which the module reports as a separate field."]'::jsonb, 0, 'THE DEPARTURE GROWS WITH THE REYNOLDS NUMBER, every row of that table. That is the whole content of the band.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 2, 'Outside the creeping flow band Stokes overstates the rise velocity. What does that do to a cut size, and why does the module warn rather than leave it to the reader?', '["It OVERSTATES the cut size, so the removal computed from that cut is too low and the design quietly carries an unstated margin nobody asked for.", "It leaves the cut size exactly where it was and moves only the Reynolds number that the device reports on the same return beside it.", "It UNDERSTATES the cut size, so a device looks as though it catches finer droplets than it does, which is the optimistic direction.", "It understates the cut size and the removal together, so the two errors cancel out of the outlet concentration."]'::jsonb, 2, 'A pessimistic model gets questioned. An optimistic one gets approved. That is why this one is stated as a number rather than left to judgement.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 3, 'At 120 micron the two routes already differ by 5.937008 percent, and the module still reports that row as inside its band. How is that consistent?', '["The gap falls inside the tolerance this module applies between its two rise velocity routes, which is why the row is marked in band.", "The band is stated on the Reynolds number, which is 0.274873 on that row, and not on the size of the gap between the two routes.", "The band is stated on the droplet diameter, and 120 micron sits under the diameter Stokes is held to here.", "The density difference of the UZERE water keeps the rise velocity under the limit the warning is stated on."]'::jsonb, 1, 'The module states Stokes to Reynolds 1 and warns above it. At 500 micron the Reynolds number is 19.883778 and Stokes overstates the rise by 78.557612 percent.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 4, 'Why is the agreement between Stokes and the full drag balance inside the band evidence of anything at all?', '["The balance is solved at a very much finer tolerance than the closed form is written to, so its answer is the reference figure that the closed form is then checked against.", "The two routes share one drag coefficient and differ only in how each of them solves for the velocity.", "The balance is the route this module actually uses, and the Stokes figure is printed only for the comparison.", "Stokes is closed form and the balance is a damped iteration on the Schiller-Naumann drag coefficient, so the two are different arguments rather than two copies of one."]'::jsonb, 3, 'Two copies of one calculation always agree. Two arguments agreeing is a result.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 5, 'For the terminal rise velocity the oracle bisects on the drag residual while the engine runs a damped iteration. Why does that pairing catch more than a second copy would?', '["Bisection is exact where an iteration is approximate, so any disagreement between them is the engine''s error alone.", "Bisection brackets a sign change and halves the interval, so it shares no step with an iteration walking towards a fixed point, and an iteration that converged to the wrong place would land somewhere else.", "The oracle runs at 400000 samples on this route, so its answer carries far less noise than the engine''s does.", "The oracle uses the Schiller-Naumann coefficient where the engine uses 24 over the Reynolds number, so the two drag laws are independent."]'::jsonb, 1, 'Bisection and damped iteration are different numerical animals, which is the whole reason the golden is worth reading.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 6, 'The oracle solves the creeping flow rise as a force balance, with the drag coefficient written as 24 over the Reynolds number and the two force expressions typed out. What does that buy?', '["There is no place in that route for an 18 to be typed, so bending the engine from 18 to 20 is caught even when the same bend is attempted in the oracle.", "It removes any need for a published rise velocity at all, a force balance written out in full being an identity of the kind that needs no source behind it.", "It reproduces the engine''s closed form exactly, so any difference at all between them is a defect.", "It lets the oracle report a Reynolds number as well, which a closed form route cannot do."]'::jsonb, 0, 'The 18 in the Stokes group is measured out of the engine rather than typed, and it comes to 18.000000000000 on the UZERE water.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 7, 'apiSeparator, plateInterceptor and hydrocyclone come out at 3.75e-14, 4.24e-14 and 3.38e-13 against the golden. What is being tolerated on those three rows?', '["A tolerance of 1e-12, which is the figure the jest suite asserts the cyclone group to.", "The oracle''s own bisection step, which stops once its bracket is narrower than the gap shown.", "The six decimal print of this digest, which is where two figures stop being comparable.", "Nothing. Both sides are exact arguments about one geometry, so the gap is floating point noise and anything materially larger would be a real disagreement to go and find."]'::jsonb, 3, 'The engine inverts a balance and the oracle marches a droplet through the vessel and bisects on the size that just clears. Two closed arguments for one number should land on the same float.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 8, 'The train rows carry gaps of 3.47e-3 on the outlet concentration and 1.80e-3 on the outlet median. Why is tightening those the wrong move?', '["Those rows carry only three published cases each, so any tolerance fitted over them would rest on far too few published conditions to be defended by any reviewer.", "The outlet median on those rows is interpolated across the single bin it falls in, and that one interpolation is where the whole of the difference on them comes from.", "The golden there is a Monte Carlo over 400000 droplets and carries its own sampling noise, so agreement at that level is the best a particle count can buy.", "The train is the one group in the file whose golden value is the engine''s own answer recorded straight back into it."]'::jsonb, 2, 'This is where a careless reviewer tightens a tolerance and breaks a good gate.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 9, 'What would it mean if the train golden ever matched the engine to machine precision?', '["That the oracle had stopped being independent, because that is what two copies of one calculation produce.", "That the particle count had been raised until the sampling noise in the golden fell well under the precision this digest prints at.", "That the quadrature over the bins had converged, which is the property the default grid of 60 bins is chosen to deliver.", "That the engine had been rewritten to track particles, which is the route the golden takes on those rows."]'::jsonb, 0, 'IDENTICAL TO TWELVE DECIMALS WOULD BE THE WEAKER RESULT on those rows. A gap is evidence in two directions.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 10, 'A reviewer finds a gap far SMALLER than the two methods being compared could justify. What does that indicate?', '["That the tolerance on that whole family of published cases is far too loose and ought to be tightened until it sits exactly at the gap the reviewer has just observed.", "That the case sits inside a band both methods are stated to, where agreement is expected and carries no information.", "That the comparison is being made at the print precision of the digest rather than at full float.", "That the two sides are sharing something they were meant to derive separately, which is the quiet failure that lets a bent engine and a bent oracle agree perfectly."]'::jsonb, 3, 'Before quoting any agreement, ask what the two routes were and what noise each of them carries.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 11, 'The golden carries expectVelocityWarning, expectStarvedWarning, expectOverloadWarning, expectResidenceWarning, expectHoldupWarning and expectBreakthroughWarning as values of its own. What does that buy?', '["A warning that fires wrongly is downgraded to a note, the field recording what was expected rather than what happened.", "The thresholds themselves are pinned, since each field carries beside it the figure it was judged against.", "A warning that stops firing fails a case rather than going quietly.", "The suite can be run without the engine''s warning strings at all, since these fields stand in for them."]'::jsonb, 2, 'Carrying the warnings as golden values is unusual and it is deliberate.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 12, 'expectStarvedWarning is carried on 5 rows and is true on 1. Why is a field that is true on every row it carries worth less than that?', '["A field that is true on every row it appears on cannot be counted at all, so the suite reports that field as unstraddled and then quietly skips over it altogether.", "A suite like that passes if the warning fires correctly, and it also passes if the warning fires always, on everything, and the cases cannot tell those two apart.", "The warning would then be the only quantity those rows pin at all, and every single row in this golden file has to pin a cut size beside whatever else the row carries.", "The threshold would be measured from one side, so the suite would locate it to within a row."]'::jsonb, 1, 'Only a field that is true on one row and false on another can measure where a boundary is. Every one of the six is straddled.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 13, 'The mediaFilterFloor group runs one flow of 0.001 m3/s through beds of 20, 200, 600, 2000, 3.61, 3.6 and 3.5 m2. What does that group establish that a cut size cannot?', '["Exactly where this module starts refusing: five beds refused below the floor, two answered at and above it, and the bed that would run the flow at the floor recorded on every row.", "That a bed wider than the floor allows still returns a cut size, carrying a warning that names its loading.", "That the breakthrough warning is straddled, the loading falling from 0.180000 to 0.001800 m/hr across the refused rows.", "That the bed area moves the cut size, which the other mediaFilter rows cannot show at the loadings they run."]'::jsonb, 0, 'It is the only group in the file whose subject is a refusal and the only one a reader cannot infer from a cut size.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 14, 'The first four beds in that group span 100.000000 times in area and every one of them is refused. Why is that span the point of the group?', '["Because the cut size goes as one over the root of the area, so a hundredfold of area is a tenfold of cut size.", "A hundredfold of bed area is the widest thing a reader could vary, and a module that answered the same on all four would be caught here and nowhere else in the file.", "Because those four rows are the only rows in the whole file that state none of the device''s own defaults.", "Because the floor is stated as an area rather than as a loading, so a span of area is what a refusal is measured in."]'::jsonb, 1, 'THOSE ARE THE FOUR BEDS A CLAMP MAKES IDENTICAL, which is the whole reason the group exists.'),
  ('producedwater', 'advanced', 'module', 'm04-the-band-and-the-balance', 15, 'In that same group 0.997230 m/hr is refused and 1.000000 m/hr answers, a gap of 0.002770 of the floor itself. What do those two rows pin?', '["The loading exponent of 0.5, which is the quantity the two rows differ by.", "The bed of 3.600000 m2 as the smallest this module will describe on that flow.", "The floor at its declared value rather than somewhere below it.", "The breakthrough loading of 25 m/hr, read off the other end of the same sweep."]'::jsonb, 2, 'Straddling as close to a boundary as a reader can usefully get is what turns a demonstration that a module CAN refuse into a measurement of WHERE it does.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 1, 'The history lesson is the one lesson of this course whose subject is history. What did the hydrocyclone in this module do BEFORE it was repaired, and what lesson is drawn from it?', '["The field was clamped at its rated value whatever the flow, so removing liners moved nothing at all, and the lesson is that a clamp deletes the input it quietly moves.", "The liner count was not an input at all, so a bank of any size reported one cut size, and the lesson is that a model has to respond to every box a user can type in.", "The field went as the square of the flow with nothing above it, so the cut size fell without limit as liners were removed, and the lesson is to sweep the input a user is most tempted to reduce and look at the direction of the answer.", "The shear penalty was applied below the operating envelope as well as above it, so the cut degraded everywhere, and the lesson is that a penalty needs a stated band."]'::jsonb, 2, 'The studio''s own shipped default ran its liners at 7.7 times their design flow. A studio that tells a designer to buy less equipment for a better answer is worse than no studio.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 2, 'The history lesson records a second defect in that same device, one level down from the first. What was it?', '["The liner LENGTH was not an input at all, and the bore reached the answer through a bare divisor on a velocity the source called residence-scaled rather than through any residence time.", "The bore of the liner was not an input at all, and the length reached the answer only through the liner volume, so just one of the two stated dimensions was able to move the reported cut size.", "Both dimensions were inputs and neither moved the answer, because the cut size was read out of a fixed table of liner sizes.", "The oil core and the half-area radius are one and the same here, so the median droplet has no distance at all to cross."]'::jsonb, 0, 'The liner this course teaches is the stated geometry the repair put there, where both dimensions move the answer for a reason a reader can follow.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 3, 'Given an oil heavier than its water, what did this module do before the first repair, and what rule does this course draw from it?', '["Every one of the five doors refused the fluid and the train then returned no verdict of any kind, and the rule drawn from it is that a refusal raised anywhere must reach the caller intact.", "One export returned a bare NaN while the four devices each refused it by name, and the rule drawn from it is that a leaf must never answer a question where its own callers have declined to.", "All five of them returned a cut size and the train raised a warning beside the result, and the rule drawn from it is that a warning is never any substitute at all for a refusal.", "One export refused by name while four devices returned a cut size of NaN with no error at all, and the rule is that when two halves of one module disagree the TRUSTING half is the bug."]'::jsonb, 3, 'The train then skipped those stages and returned a spec verdict computed over whatever ran. The repaired engine refuses the identical bad fluid at all five doors at once.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 4, 'Two models in this engine were DEAD before the first repair. What made the flotation model dead?', '["An attachment efficiency applied unchanged to every cell whatever its gas rate, which held the cut size at one figure.", "An attachment fraction that was exactly one across every input a user could type, which made the bubble size, the gas rate and the residence time decorative and made the two kinds of cell one device behind two menu entries.", "A residence time taken from the plan area rather than from the cell volume, so the cell depth never reached the answer.", "A bubble rise read from Stokes at every bubble size, so a Reynolds number in the tens was never reported at all."]'::jsonb, 1, 'THE LESSON IS THE PROBE: sweep every input and check that it moves the answer.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 5, 'The media filter was the other dead model. What was wrong with it before that first repair?', '["It computed its cut size out of the grain size alone, so the depth of the bed never entered into the answer it reported.", "It reported the removal at its own reference droplet as though that figure were the removal over the whole droplet distribution.", "It computed its removal twice by two routes that disagreed, and the train read the route the gate did not validate.", "It inverted the penetration law at the wrong depth, so every cut size was out by the root of the bed depth."]'::jsonb, 2, 'If a module holds two opinions about one quantity, delete one. There is ONE route through this model now.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 6, 'Before the repair a train that removed nothing showed its droplet median falling. The history lesson says why. What was it?', '["The outlet bins were normalised by the surviving volume and the inlet bins were not, so the two medians were taken on different totals.", "The inlet median was the typed d50 and the outlet median was measured off the bins, so the two were not the same kind of number.", "The inlet median was interpolated and the outlet median was read as a bin midpoint, so the outlet was quantised downward every time.", "The truncated tail was absorbed into the outlet distribution alone, which dragged its median towards the fine end of the grid."]'::jsonb, 1, 'THE LESSON IS THE BASIS: two numbers a reader will compare must be measured the same way, and the module should say on its own return that they are.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 7, 'This course found a defect of its own in the media filter while building the digest against the already repaired engine. What was it, and what did the second repair put in its place?', '["It clamped its own loading rate up to a floor and said nothing, so beds of completely different area reported the same filter coefficient and the same cut size to every digit, and the repair is to REFUSE by name.", "It refused every bed below its reference loading of 10 m/hr, and the repair lowered that floor to 1 m/hr.", "It warned below the floor and answered anyway, and the repair turned that warning into a clamp reported on the return.", "It took its loading rate from the bed depth rather than the bed area, and the repair made the area an input."]'::jsonb, 0, 'The clamp was in the oracle too, so the independent check agreed with it. A guard that quietly moves an input is a guard that deletes the input.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 8, 'One device threshold in this module was still written bare inside the sentence that reported it. Which was it, and what lesson does the history lesson draw?', '["The breakthrough loading, which was written bare inside the warning that reported it and which the module now declares at 25 m/hr in its own frozen constants object where a reader can find it.", "The overload turndown of the liner bank, which was written inside the shear penalty itself rather than being declared into the frozen constants object where any reader could go and find it for themselves.", "The swarm holdup limit of this module, which was compared against inside the holdup warning that reported it and which is now simply an input that a caller supplies for themselves.", "The flotation residence warning, which compared against a bare 60 written inside its own message, and the lesson is that a threshold a reader cannot find is a threshold nobody reviews."]'::jsonb, 3, 'The droplet grid''s two floors were bare the same way. A warning should quote the figure it judged against so a reader can disagree with it.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 9, 'The volume median had a silent way back to the answer the first repair had just removed. What was that route?', '["It interpolated when a bin carried its edges and fell back to the bin midpoint when it did not, reachable by one caller handing over midpoints alone, with nothing on the return saying which route had run.", "It interpolated on the outlet distribution and read the inlet from the typed d50, which is the basis defect appearing in a second place.", "It fell back to the analytic median of the log-normal whenever the bin set arrived empty, which is an answer no bin set supports.", "It reported a midpoint whenever the median fell in the outermost bin, where there is no edge available to interpolate against."]'::jsonb, 0, 'A fallback that answers is worse than a refusal, because it is an answer nobody can tell from the right one. The leaf returns NaN now and its callers turn that into a named refusal.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 10, 'Thirty five defects were run one at a time against the suite before the first repair and again after it. What were the two results?', '["Before it, 16 of the 35 left the suite green. After it, 8 of them still do.", "Before it, all 35 were caught in the engine while 8 were missed in the oracle. After it, none are missed.", "Before it, 22 of the 35 left the suite fully green. After it, 0 of 35 do.", "Before it, 27 of the 35 left the suite green. After it, 22 of them still do."]'::jsonb, 2, 'Twenty seven were planted in the engine alone and eight in the engine and the oracle together, and 16 of the first group and 6 of the second survived.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 11, 'How large is the planting battery this course was built beside, and what does it show?', '["Thirty five in all, each of them run on its own against the vendored suite, and none of those thirty five is able to leave the suite fully green.", "Seventy eight in all, one for each of the tests carried in the vendored suite, and none of those is able to leave the suite fully green either.", "Sixty in all, run together in one single pass against the vendored suite, and not one of the sixty is able to leave that suite fully green.", "Sixty in all, the thirty five re-run plus twenty four more and one self-test of the runner, and none of the sixty leaves the suite green."]'::jsonb, 3, 'A battery run one defect at a time measures the suite''s ability to catch each defect separately. Many at once measures nothing useful, because one catch hides all the rest.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 12, 'A defect planted in the engine and the oracle at the same time is the hard case, because a golden regenerated from a bent oracle agrees with a bent engine perfectly. What catches those now?', '["The measured gap table printed in this digest, since a bent pair of files will agree with itself very much more closely than two genuinely independent routes ever should.", "Three things: a route with no place to type the constant, the identities that need no source, and an explicit pin with the value typed by hand in the test file.", "The negative controls carried by every single family in the whole suite, each of which is asserted to stay green on every row of the family it belongs to.", "The straddled warning fields in the golden file, since a bent pair of files moves a threshold and a straddle on both sides of it will detect that move at once."]'::jsonb, 1, 'None of those three is a comparison between the engine and its golden. They are the checks that step outside the pair.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 13, 'The independent oracle holds its OWN second copy of the declared constants. What does the agreement between the two files establish about those numbers?', '["Nothing. On the constants the two are copies rather than arguments, so if a value is wrong they are both wrong together.", "A validation, since the oracle was written separately from the engine and arrived at the same values for each of them.", "A pin at twice the strength, since two separate files now have to be edited together before any one constant can be moved.", "It depends on the constant, since the ones that also appear in the golden file are validated by it."]'::jsonb, 0, 'Six of the eight defects planted in the engine and the oracle together are caught by that pin and by nothing else, which is a statement about how much of this module a pin is carrying.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 14, 'One negative control in this suite records a fact about its own subject rather than a round number. Which one, and what is the fact?', '["The filter control fails on seven of its eight rows, the row sitting at the reference grain being the one where the grain size ratio comes out at exactly one.", "The train control fails on two of three rows, the Monte Carlo noise in the golden covering the third of them.", "The cyclone control fails on four of five rows and not five, because a turndown of exactly one is the one case a wrong field exponent cannot move.", "The cyclone control fails on all five of its rows, which is what a control asserted to fire is supposed to do."]'::jsonb, 2, 'A control asserted to fail on all five would have been quietly wrong about the physics, and the honest number is the one that matches what the exponent can actually reach.'),
  ('producedwater', 'advanced', 'module', 'm05-what-a-gate-can-catch', 15, 'After a planting battery has been run, what specific claim does a green suite support?', '["That the engine is validated outright, since a battery that no planted defect survives has exhausted the ways it could have been wrong.", "That these particular defects, introduced this way, would each have been caught, which is a much smaller claim than validated.", "That every number the module computes is either derived or validated, the pinned ones being covered by the exact key set match.", "That the oracle is fully independent of the engine, since an oracle that was not would have let at least some of the sixty through."]'::jsonb, 1, 'A green suite is a measurement of the suite until somebody plants a defect and watches. That is a claim you can actually defend.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 1, 'This module sorts every number it stands on into four kinds. What are they, and how many numbers sit in the calibrated kind?', '["Derived, declared, validated and held for literature, with exactly one number in the validated kind of the four.", "Derived, declared, calibrated and held for literature, with exactly one number in the calibrated kind.", "Derived, declared, calibrated and held, with six numbers in the calibrated kind.", "Measured, declared, pinned and held, with exactly one number pinned rather than measured."]'::jsonb, 1, 'A reader who can place a number in the right kind has learned the main thing this module teaches.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 2, 'Sharpness 2 and sharpness 3 both appear on one train return. Which kind of number is each of them?', '["Both of them are declared values, and the two figures taken together are the customary band into which this module holds the grade curve of any one of its own devices to have to fall.", "Three is derived out of the reduced-efficiency form and two is declared for the two interception devices.", "Two is calibrated, so that a flotation cell lands in its customary range, and three is derived from the form.", "Two is DERIVED for the interception devices, because their capture rate goes as the square of the droplet diameter, and three is DECLARED for the gravity and centrifugal devices."]'::jsonb, 3, 'An exponential in the square of the reduced size has the same half point and the same leading power as the reduced-efficiency family at m equal to two. It was not chosen.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 3, 'The grade efficiency AT the cut size is 0.500000000000 at ten micron against a ten micron cut. Which kind of number is that, and where does it hold?', '["Derived, and at every sharpness, because the reduced-efficiency form is r over one plus r.", "Declared, and only at the sharpness of 3 that the gravity and centrifugal devices are given here.", "Derived, and only at the sharpness of 2 the interception devices use, the exponential having its half point there.", "A calibration, chosen so that a cut size in this module means what the literature takes a cut size to mean."]'::jsonb, 0, 'That is what a cut size MEANS, and there is nothing to check because it follows from something else on the page.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 4, 'What does this module state about the dissolved and soluble oil floor?', '["That it is the outlet concentration below which no device in this module removes anything at all, and that it is reported back on the return as the truncated tail.", "That it is declared in the frozen constants object and applied to every train return without being asked for.", "That there is one under any outlet a train can reach, and that no value for it is stated here, so the value is the caller''s own.", "That it exists, and that it customarily falls between the two figures the verdict block of the digest prints."]'::jsonb, 2, 'The existence is stated on every train return. The floor only matters where a train''s DISPERSED prediction falls below it.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 5, 'Every API 421 return that carries the horizontal velocity check also carries velocityRuleComplete false. What is missing?', '["The short-circuit allowance F, which the standard states and which this module defaults to 1.5.", "The depth of the basin, which does not enter the cut size and so is not checked against the rule.", "The published limit itself, which this module holds at 0.015000 m/s while a source is awaited.", "The second half of the rule. The standard also limits the horizontal velocity to a multiple of the design droplet rise velocity, and that half is not in this repository."]'::jsonb, 3, 'A basin that passes this check has passed HALF A RULE. The OGBOTOBO basin runs at 0.013591874698 m/s against the 0.015000 m/s fixed limit with its warning absent.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 6, 'The filter coefficient column falls as the CUBE of the grain size ratio. What is the status of that exponent?', '["Held for literature. The interception derivation gives the inverse cube, and no bed data in this repository can check it.", "Derived, and validated by the published bed cases in the golden file, three of which state a grain size some way away from the module''s own reference.", "Declared, since it is one of the constants that the jest suite pins by literal with an exact key set match over the whole frozen object.", "Calibrated, since the reference grain of 800 micron was chosen to put the coefficient ratio at exactly one."]'::jsonb, 0, 'It is a strong dependence and the input moves the answer by a large factor. A reader should treat the grain column as the model''s statement rather than as a measurement.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 7, 'What makes attachmentEfficiency different from every other number in this module?', '["It is the one number that is not exported at all, so that a caller has no way of moving it.", "It is the one number with no derivation at all, chosen so a cell at the module''s own default conditions cuts in the range induced gas flotation is customarily credited with.", "It is the one number this module refuses to accept from a caller, because moving a calibration would invalidate the cut.", "It is the one number that enters the answer linearly, so that an error in it passes through whole."]'::jsonb, 1, 'It is an input, so a caller with a vendor curve can move it. Nothing in this course presents it as published.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 8, 'Moving the attachment efficiency moves a flotation cut size with its own square root. Why is the square root the reassuring part?', '["Because the cut then depends on the square of the efficiency, so a factor of two in it is a factor of four in the answer.", "Because the efficiency cancels out of the ratio column entirely.", "An error in the number you know least about is damped on its way to the answer rather than passed through whole.", "Because the root is taken against the bubble diameter as well, so that the two uncertainties cancel each other out."]'::jsonb, 2, 'Work out the power a calibration enters at, because the power tells you how much of your uncertainty survives the calculation.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 9, 'No graded answer in this course depends on the attachment efficiency. What is the reason given?', '["Grading an answer that rests on a calibration would be grading the calibration.", "The value is not exported, so a learner reading the module would have no way of finding it.", "Flotation is taught at Professional level, and graded fields are drawn from the Expert tier alone.", "The cut size it produces falls outside the band this module states its rise velocities to."]'::jsonb, 0, 'It is the ONE number in this module with no derivation at all, and it is an input so that a caller with real data can move it.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 10, 'The frozen constants object carries 55 keys, and a table of the module''s chosen fit and device values lists only part of them. What are the rest?', '["Copies of the table''s own entries restated in other units of measure, kept in the same object so that a caller never has to convert between them.", "Mostly band edges and limits a refusal or a warning is judged against, plus two defaults, the interception sharpness and the one calibration.", "They are the held numbers, kept in the object with no value at all.", "They are the golden file''s expectation fields, carried so the suite reads them."]'::jsonb, 1, 'Twelve are band edges and limits, such as the -10 to 200 C of the viscosity fit and the 5 to 100 degrees of API gravity. The rest are the bed depth and train spread defaults, the interception sharpness of 2 and the attachment efficiency of 0.01.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 11, 'How does the jest suite treat the declared constants, and what does that guarantee?', '["It checks every one of them against the golden file, so that any constant which moves then goes on to fail each and every one of the published cases that happen to touch that key.", "It asserts that each one of them lies inside its own customary band, which then leaves any one of these constants entirely free to move about inside the whole of that band unremarked.", "It pins them by literal with an exact key set match, so adding or removing one fails until the pin is updated, which makes moving one a reviewed act rather than a silent one.", "It recomputes each of them from the published cases, so a constant that no case reaches is left unpinned in the suite."]'::jsonb, 2, 'The module''s own comment says pinning is all any gate can do with these, and the test says in as many words that a pin is not a validation.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 12, 'A designer asks this module what the hydrocyclone''s reject stream will hand to the downstream oil handling. What does it carry?', '["The reject split, which is one part of the ideal capture statement that the hydrocyclone bank carries on each one of its own returns alongside the reported cut size itself.", "The reject rate, derived from the turndown of the liner bank and from the field it develops, with the oil recovery read off the train as that one stage''s own removal.", "The oil recovery balance alone, which is the quantity the stage removal percentage already reports.", "Nothing. There is no reject stream or oil recovery balance in this engine, which returns what a device removes from the water and says nothing about where it goes."]'::jsonb, 3, 'How much water leaves with the oil is a real design quantity that decides what the downstream oil handling has to accept, and it is absent here.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 13, 'How close does this module come to describing a bed fouling over time?', '["It warns above the loading rate at which beds lose depth capture, and it carries no time axis at all.", "It refuses above the breakthrough loading and warns below the floor, which between them bound the life of a bed.", "It reports a backwash cycle length, taken from the loading rate and the removal at the reference droplet size.", "It carries a fouling factor among its declared constants, which is applied to the filter coefficient of the bed."]'::jsonb, 0, 'An approximation is a number that is a bit wrong and that you can bound. An absence is a mechanism that is missing.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 14, 'What does this engine say beside every hydrocyclone cut size, and what kind of statement is it?', '["That the cut size is a calibrated figure, landed in the range de-oilers are customarily credited with.", "That the cut size carries a vendor performance curve from this repository, applied to it as a shear penalty.", "That the capture is an IDEAL, with re-entrainment, the reject split and the shear the liner itself applies left out, and that field de-oilers are customarily credited with a coarser cut than this, which is a statement about what the model leaves out rather than a number.", "That the capture is an ideal and that a field de-oiler is customarily finer, so the figure is a conservative one."]'::jsonb, 2, 'No vendor performance curve exists in this repository to calibrate against, and that statement belongs beside every cyclone cut size this course prints.'),
  ('producedwater', 'advanced', 'module', 'm06-where-the-method-stops', 15, 'Why does the order identity sit so comfortably beside the list of absences?', '["The absences all sit downstream of the last stage, which is where the order of the plant has stopped mattering.", "The model does not care about order because it does not carry the mechanisms that make order matter, which are fouling, plugging and how much oil each device can take in its reject.", "The identity is asserted on the outlet alone, and every absent mechanism moves a stage removal instead of it.", "The absent mechanisms are held for literature, so the identity is what this module offers a designer in their place."]'::jsonb, 1, 'The invariance and the absence are the same fact seen twice.'),
  ('producedwater', 'advanced', 'final', null, 1, 'One of the three published train cases is described as three identical devices, to show the coupling. Why put a case like that in a golden file at all?', '["Because the coupling is what a fixed efficiency table throws away, so it needs a published case of its own, checked by a route with no bins in it.", "Because three identical devices are the only arrangement in which the order identity can be asserted at all.", "Because a train of identical devices is the one case where the engine and the particle tracking agree exactly.", "Because the Suite''s own shipped default train has three stages in it, so this published case is simply that same train with all three of its devices equalised."]'::jsonb, 0, 'The golden there is 21.720064 ppm against the engine''s 21.685537, with outlet medians of 8.385841 and 8.400899 micron, all of it written by particle tracking over 400000 droplets.'),
  ('producedwater', 'advanced', 'final', null, 2, 'In the five identical device sweep the last column reads 1.000000, 0.486641, 0.313934, 0.233950 and 0.187835. What is each of those a ratio of?', '["That stage''s outlet concentration over the concentration entering the train.", "That stage''s cut size over the outlet droplet median arriving at it.", "That stage''s own removal over the first stage''s removal.", "The volume surviving that stage over the volume that survived the stage before it."]'::jsonb, 2, 'It is derived, each stage removal over the first stage''s. The fifth identical device removes 12.284239 percent where the first removed 65.398946.'),
  ('producedwater', 'advanced', 'final', null, 3, 'Running the OGBOTOBO devices in reverse, the API 421 basin reports 0.006985 percent. Where in that train is the basin, and what is the figure telling you?', '["First, and it is telling you that a coarse device standing on raw water removes almost nothing that is worth having.", "Last, and it is telling you that the basin has been sized below the cut size the water needs.", "Second, and it is telling you that the reversal has put two interception devices ahead of it.", "Last, and it is telling you what the three finer devices ahead of it had already taken out of the water."]'::jsonb, 3, 'As designed, at the head of the train, the same basin reports 3.237437 percent. Nothing about the vessel changed between the two runs.'),
  ('producedwater', 'advanced', 'final', null, 4, 'A stage removal means nothing without knowing what reached that stage. Which figure on a train return tells you what reached it?', '["The cut size of the stage itself, which the engine sizes against the water arriving at it.", "The outlet droplet median of the stage before it.", "The overall removal, which carries the state of the water at every position in the plant.", "The truncated tail, which says how much of the arriving distribution the bins did not cover."]'::jsonb, 1, 'Down the OGBOTOBO train those medians run 13.476136, then 3.972384, then 3.415699 micron, so the last two devices work on water whose median sits below every cut size in the plant.'),
  ('producedwater', 'advanced', 'final', null, 5, 'After the fifth of five identical 9 micron devices the outlet droplet median is 3.670618 micron. What does that figure say about the water arriving at that last vessel?', '["Its typical droplet is just above the cut size, which is why the stage still removes 12.284239 percent.", "It is numerical dust, so no further device in this module can be applied to it at all.", "Its typical droplet is well under the cut size of the device it is being handed to.", "It is finer than the dissolved and soluble oil floor this module carries for such waters."]'::jsonb, 2, 'A device placed where the water is already fine is being asked for its worst performance, and the number it returns will say so.'),
  ('producedwater', 'advanced', 'final', null, 6, 'Two competing trains are quoted at you, each with its four stage removals. What must you compare, and why?', '["Their outlets, because the stage numbers are functions of the arrangement and will differ for reasons that have nothing to do with performance.", "Their stage removals in order, because the arrangement is what the two designs actually differ in.", "Their largest stage removals, because the device doing most of the work decides the train.", "Their overall removal percentages alone, because an outlet concentration depends on the inlet it started from and the two inlets quoted at you may well differ."]'::jsonb, 0, 'Reordering four devices moved the per stage figures by as much as 57.344778 percentage points and left the outlet at 160.391597 ppm.'),
  ('producedwater', 'advanced', 'final', null, 7, 'A vendor quotes a removal percentage for a device. What has to arrive with it before the figure can be carried to another plant?', '["The cut size, since two devices with the same cut size remove the same fraction of any oil.", "The sharpness of the grade curve, since 2 and 3 are worth real percentage points of removal.", "The position in the train, since a removal quoted at one position transfers to the same position elsewhere.", "The water it was measured on, because a removal is a property of a device and a water together."]'::jsonb, 3, 'The same walnut shell filter honestly reports 14.382082 percent in one position and 60.582215 percent in another.'),
  ('producedwater', 'advanced', 'final', null, 8, 'The published bin grid group carries one row at d50 12 and sigma 0.9 among rows at d50 30 and sigma 0.7. What does that row add?', '["It shows the truncated tail moving with the sigma of the distribution, which the rows carrying a sigma of 0.7 cannot show on their own.", "It shows the median identity holding at another median and another spread, rather than only at the one the rest of the group uses.", "It shows the grid refusing a distribution too narrow to describe on 60 bins.", "It shows the interpolation working where the median falls inside the coarsest bin."]'::jsonb, 1, 'The median column reproduces the stated d50 on every row of the group: 30.000000, 30.000000, 12.000000, 30.000000 and 30.000000.'),
  ('producedwater', 'advanced', 'final', null, 9, 'At the tightest row of the cut sweep the module reports 43.150877 ppm and an outlet median of 2.179329 micron. What are those two figures doing together?', '["Disagreeing, since the concentration has fallen much further than the median, which is the binning error.", "Converging, since at a tight enough cut both columns approach the floor the module reports for dust.", "Falling together, which is the property the whole sweep is asserted on and the one a quantised median cannot have.", "Crossing, since below a cut of 3 micron the median stops tracking the cut size and the outlet concentration carries the whole answer alone."]'::jsonb, 2, 'The medians fall monotonically as the cut tightens, and a jest test asserts it.'),
  ('producedwater', 'advanced', 'final', null, 10, 'Which of the module''s identities is the one a bin set has to satisfy before anything measured on it can be trusted?', '["The volume median of a log-normal bin set equals its own d50.", "The grade efficiency at the cut size is exactly one, since a cut size removes everything above it.", "The flotation cell count moves the cut size in proportion to the total gas fed to the unit.", "A plate pack cut is proportional to the channel height the pack is sliced into."]'::jsonb, 0, 'On the UZERE inlet it returns 26.000000 micron against a typed 26, on every grid in the digest.'),
  ('producedwater', 'advanced', 'final', null, 11, 'Two rows of the published grid group differ in nothing but their bin count, one at 60 and one at 30. What is identical across them, and what does that pin?', '["Only the median, the tail being the quantity the bin count is there to move.", "Both the median at 30.000000 micron and the truncated tail at 0.000063342484, which pins the bin count as moving neither of them.", "Only the tail, the median being interpolated and so free to move with the bin edges.", "Neither, since halving the bin count halves the resolution and both figures respond to it."]'::jsonb, 1, 'Resolution decides how finely volume is apportioned inside the covered range. It does nothing about what lies outside it.'),
  ('producedwater', 'advanced', 'final', null, 12, 'A jest test is pointed at the outlet median column of the cut size sweep. What exactly does it assert?', '["That each figure sits inside one bin of the one before it, which is the resolution the grid was asked for.", "That the first figure reproduces the typed d50 of the inlet distribution to within the print precision.", "That the column and the outlet concentration column fall in the same proportion at every row.", "That the figures fall monotonically as the cut tightens."]'::jsonb, 3, 'A quantised median shows up as a flat run in a column that should be strictly falling, which is a defect no spot check at one condition can see.'),
  ('producedwater', 'advanced', 'final', null, 13, 'Two of this module''s declared constants are floors on the droplet grid. What are they?', '["defaultNBins at 60 and defaultSpanSigma at 4, which are the floors as well as the defaults.", "minNBins at 30, which is the smallest bin count in the published grid group, and minSpanSigma at 4.", "minNBins at 10, the fewest bins the distribution will be described on, and minSpanSigma at 3, the fewest sigma either side of the median the grid must span.", "sigmaMax at 2 and tdsMaxPpm at 300000, the two figures that bound a distribution this module will describe."]'::jsonb, 2, 'Both sit in the frozen constants object with the rest of this module''s choices, so a reader can find the figure the grid is held to rather than infer it.'),
  ('producedwater', 'advanced', 'final', null, 14, 'The reported truncated tail is taken over twice the module''s own cdf at the lower span edge. What must that ratio come out at?', '["One.", "Zero, since the normalisation has already absorbed the tail out of the bins.", "The truncated tail itself, since the cdf below the span edge is one half of it.", "The bin count, since the tail is apportioned across the bins the grid carries."]'::jsonb, 0, 'It comes out at that value on every bin count swept, so what the bins failed to cover and what the analytic distribution puts beyond the span edges are the same quantity.'),
  ('producedwater', 'advanced', 'final', null, 15, 'How many names does this module export, how many are callable, and what are the rest?', '["16 exported names, 13 of them callable, and 3 leaves that answer with a bare number.", "20 exported names, 16 of them callable, and 4 frozen objects or strings.", "20 exported names, all of them callable, and 4 that carry no error contract.", "13 exported names carrying the error contract, plus 3 leaves and 4 frozen objects."]'::jsonb, 1, 'Of the callable ones, 13 carry the error contract and 3 are LEAVES that answer with a bare number and say they have no answer with a bare NaN.'),
  ('producedwater', 'advanced', 'final', null, 16, 'A plate pack is called with no water viscosity at all. What comes back?', '["A cut size computed at the module''s own default water viscosity, carrying a warning that names the substitution it made.", "A bare NaN, since the viscosity enters through a leaf and a leaf has nowhere to put an error.", "A withheld verdict, since a stage that cannot be sized has not run and there is then no whole train left to give a judgement on.", "A refusal saying a plate pack needs the water viscosity in Pa.s to size its cut, and this is undefined."]'::jsonb, 3, 'A plate pack needs the viscosity to size its cut, so the module names the input it wanted and the unit it wanted it in.'),
  ('producedwater', 'advanced', 'final', null, 17, 'An API gravity of -131.5 is passed in, which is the value where the specific gravity denominator goes to zero. What does the module say?', '["That the specific gravity denominator is zero at this value, so the crude density has no answer.", "That the oil must be lighter than the water for it to rise, which it cannot be at this gravity.", "That it holds API gravity to 5 to 100 degrees and this is -131.5.", "That the crude density fit is stated from 0 to 100 C and this call falls outside it."]'::jsonb, 2, 'It refuses on its stated band rather than on the arithmetic, and it names the value it was given. 100.1 API is refused by the same sentence from the other end.'),
  ('producedwater', 'advanced', 'final', null, 18, 'The train with the plate area box cleared still reports 707.618822 ppm and 60.687843 percent. What are those two figures taken over?', '["The 2 of 3 stages that actually ran.", "The whole three stage train, with the plate pack contributing nothing to either figure.", "The stage that did not run, which is why they are reported beside its name and its cause.", "The two stages that ran, with the verdict then taken over the same two."]'::jsonb, 0, 'The train is reported as complete no, with the skipped stage named in its own list, so the two figures can be read for what they are.'),
  ('producedwater', 'advanced', 'final', null, 19, 'Every warning in this module names a quantity and a threshold. What does that let a reader do?', '["Recompute the answer without the warning, since the threshold is what the figure was scaled by.", "Disagree with it, because the figure the module judged against is on the screen beside the answer.", "Decide whether the run should be reported at all, since a warned figure is provisional.", "Locate the case in the golden file, since every threshold in the module is straddled by published rows."]'::jsonb, 1, 'A threshold a reader cannot find is a threshold nobody reviews, which is why the module puts the figure it judged against into the sentence.'),
  ('producedwater', 'advanced', 'final', null, 20, 'Nothing is typed into the specification box, and the train itself runs all the way through. What comes back?', '["Every concentration it computed, with meetsSpec no, since an unmet specification and an absent one are the same case.", "A refusal, since a verdict was asked for and the input needed to give one is missing.", "Every concentration it computed, with meetsSpec null and the reason that no discharge specification was given.", "Every concentration it computed, with meetsSpec true, since nothing has been failed."]'::jsonb, 2, 'This module states no discharge limit of its own and has none to fall back on. The specification is the caller''s, out of the caller''s own permit or regulation.'),
  ('producedwater', 'advanced', 'final', null, 21, 'A leaf could return a plausible number instead of a NaN when it has no answer. Why is that the dangerous option?', '["A plausible number is a great deal harder to test for than a NaN is, so every one of the callers above it would need more code.", "A plausible number would make the leaf disagree with the device sitting above it, and the two halves of any one module have to agree.", "A plausible number cannot be distinguished from the module''s own defaults, which are also plausible.", "A plausible number propagates silently through everything downstream and arrives at a reader looking exactly like a result."]'::jsonb, 3, 'A leaf has two honest options and one dishonest one. It can give the right answer, it can say it has none, or it can return something that looks like one.'),
  ('producedwater', 'advanced', 'final', null, 22, 'The creeping flow band is not checked once for the water. What does every device in this module report and warn on?', '["The Reynolds number of its OWN cut droplet, so a cut size that has landed outside creeping flow says so on the same return that carries it.", "The Reynolds number of the median droplet in its inlet distribution, which is the droplet the grid is built around.", "The ratio of its Stokes velocity to its full drag balance velocity, which is the gap the band is stated on.", "The Reynolds number of the coarsest droplet on its grid, which is the first one to leave the band."]'::jsonb, 0, 'A coarse basin on a heavy oil is exactly where this bites. The density difference is small, so the cut droplet is large, its Reynolds number climbs, and the number on the screen is the one the warning is about.'),
  ('producedwater', 'advanced', 'final', null, 23, 'What does the golden file''s rise group pin, across its 5 rows?', '["The full drag balance at bubble Reynolds numbers below one, where Stokes and the balance agree.", "Stokes, its Reynolds number, and the measured gap to the real drag balance.", "The basin cut sizes, with the velocity warning expected true on every row that carries it.", "The binned quadrature against a finer quadrature."]'::jsonb, 1, 'One published row across the basin, plate and rise groups sits OUTSIDE the creeping flow band on purpose, because a gate that only ever sees cases inside a band cannot tell that the band is being policed.'),
  ('producedwater', 'advanced', 'final', null, 24, 'The golden''s cdf group runs 7 rows. What is it checked against, and on what tolerance?', '["The module''s own log-normal bin set, taken on the tolerance that the median identity is asserted to.", "A Monte Carlo of the same series, on a tolerance the sample count is chosen to reach.", "The C library''s own erf, on an absolute tolerance that is the series own published accuracy.", "The truncated tail at each of the spans, taken on the tolerance that the tail identity is asserted to."]'::jsonb, 2, 'A tolerance chosen after the fact is not a test. This one is the accuracy the series itself is published to.'),
  ('producedwater', 'advanced', 'final', null, 25, 'How large is the golden file this course prints from?', '["14 groups and 60 rows, one row for every bin on the module''s own default droplet grid.", "14 groups and 78 rows, one row for each test in the vendored jest suite.", "6 groups and 77 rows, one group for each family the measured gap table reports.", "14 groups and 77 rows."]'::jsonb, 3, 'Every one of those groups pins something different, from the error function series against the C library to the whole train by particle tracking.'),
  ('producedwater', 'advanced', 'final', null, 26, 'At least one row per device in that file states NONE of that device''s own defaults. Why is that a rule rather than an accident?', '["Because a suite whose every case runs at the defaults cannot tell a default from a derivation.", "Because a row at the defaults would duplicate the row the digest already prints for that device.", "Because the defaults are pinned by literal in the jest suite, so a case running at them checks nothing new.", "Because a golden row has to straddle a threshold, and no default sits on a threshold."]'::jsonb, 0, 'A golden file has to be built to that rule. A case that runs at the defaults lets the code recall rather than compute.'),
  ('producedwater', 'advanced', 'final', null, 27, 'Every row of the mediaFilterFloor group, refused and answering alike, carries an areaAtFloorM2 of 3.600000 m2. What is that number?', '["The smallest bed in the group, which is the one row where the module still answers.", "The bed that would run that flow at the floor, so a reader who wanted an answer below it is told what to change and by how much.", "The area at which the filter coefficient equals the value declared at 10 m/hr.", "The bed area the golden expects, against which the engine''s own area is compared."]'::jsonb, 1, 'The refusal names four things and each is doing work: the loading it was given, the floor it is under, the reference loading the coefficient is declared at, and the bed that would reach the floor.'),
  ('producedwater', 'advanced', 'final', null, 28, 'How does the oracle reach the filter cut size, and why is that not a restatement of what the engine does?', '["It integrates the grade curve over the droplet distribution and reads the cut off the removal.", "It re-derives the filter coefficient from the reference triple and compares the two coefficients.", "It marches the bed layer by layer and bisects out the droplet whose marched removal is exactly one half, where the engine inverts the penetration law in closed form.", "It tracks 400000 droplets through the bed and counts the half that fails to come out."]'::jsonb, 2, 'The cut size the train reads is an inversion of the depth filtration the oracle marches layer by layer.'),
  ('producedwater', 'advanced', 'final', null, 29, 'Six of the eight defects planted in the engine and the oracle at once are caught by an explicit pin and by nothing else. What is that a statement about?', '["How well the identities cover the module, since they catch the other two of the eight.", "How independent of the engine the oracle really is, given that a pin is the strongest check a golden file can carry.", "How many of the declared constants turn up in the published cases at all, which is the one place where a pin is able to fail.", "How much of this module a pin is carrying, given that a pin records only that a chosen value has not moved."]'::jsonb, 3, 'A pin cannot fail for being wrong, only for having changed. Both the code and the test say so.'),
  ('producedwater', 'advanced', 'final', null, 30, 'How does the oracle reach the hydrocyclone cut, and what does it add on top of that route?', '["It marches the radial migration with the field re-derived through the TANGENTIAL VELOCITY rather than the flow ratio, and adds a Monte Carlo over starting radii uniform by area.", "It marches the radial migration using the same turndown the engine uses, and adds a sweep of the liner count.", "It bisects on the droplet that just reaches the wall in the residence time, and adds a check of the shear penalty.", "It integrates the grade curve at the reported cut size, and adds the captured fraction at twice the cut."]'::jsonb, 0, 'The engine computes the field from the flow through one liner over its design flow. The oracle gets there another way, which is what makes the agreement mean anything.'),
  ('producedwater', 'advanced', 'final', null, 31, 'The plate route in the oracle marches two different channel heights and asserts something about the two answers. What, and why does it matter?', '["That the two heights bracket the true cut size, so the answer can be bisected between them.", "That a plate pack cut does not depend on how the pack is sliced into channels, which is a property of the pack rather than of how it was drawn.", "That the cut size scales with the channel height, which is how the plate count enters the answer.", "That the pack efficiency factor of 0.7 is recovered from the ratio of the two answers."]'::jsonb, 1, 'The golden carries it as `channelHeightIndependence`, a column on the plate rows rather than a sentence about them. That column is the proof rather than the claim.'),
  ('producedwater', 'advanced', 'final', null, 32, 'A gate that restates the formula the engine uses validates nothing. What has to be true of an oracle instead?', '["It has to be written by somebody other than the author of the engine.", "It has to be run at a very much tighter tolerance than the engine is, so that any disagreement between the two is the engine''s own.", "It has to reach every answer BY A DIFFERENT METHOD, so that the difference between the routes is what the agreement is worth.", "It has to cover every one of the published cases in the golden file, so that no answer the engine gives goes unchecked."]'::jsonb, 2, 'The engine inverts a balance and the oracle marches a droplet and asks when it arrives. The two share the geometry, the fluid properties and a second copy of the declared constants, and the routes share nothing.'),
  ('producedwater', 'advanced', 'final', null, 33, 'The lesson on what was repaired in this engine is framed as HISTORY. Where does this course keep repair history?', '["In that one framed lesson and nowhere else, while every other lesson, panel and figure is the repaired engine answering now.", "In any lesson that teaches the repaired behaviour, so that a reader can see the before and the after together.", "In the panels, where a reader can drive the old model and the new one side by side.", "In the golden file, which carries the old answers as expectation fields the suite asserts against."]'::jsonb, 0, 'A number from the old model that reached a reader without the frame would simply tell them something false about how this engine works.'),
  ('producedwater', 'advanced', 'final', null, 34, 'The history lesson records what the studio''s own shipped default did before the first repair. What was it?', '["It ran its bed at 7.7 times the loading rate the filter coefficient is declared at.", "It ran a cell at 7.7 times the gas to water ratio the module now holds a cell to.", "It ran a basin at 7.7 times the horizontal velocity the API 421 check allows.", "It ran its liners at 7.7 times their design flow."]'::jsonb, 3, 'That is the state a studio was shipped in, and it is why that lesson is framed as history rather than told as an anecdote.'),
  ('producedwater', 'advanced', 'final', null, 35, 'Why do the identities survive a compromised oracle where the published comparisons do not?', '["An identity is asserted at a tighter tolerance, so a bend big enough to matter cannot hide inside it.", "An identity is checked against the definition rather than against another program, so it does not care what the oracle says.", "An identity is checked on the engine and the oracle separately, so a bend in one shows as a disagreement.", "An identity is regenerated with the golden, so a bent oracle writes an identity that fails on its own terms."]'::jsonb, 1, 'If somebody bends the engine and bends the oracle to match, the golden regenerates and agrees perfectly. The identity does not move.'),
  ('producedwater', 'advanced', 'final', null, 36, 'Of the six things held for literature, one is also something else. Which, and what else is it?', '["The dissolved oil floor, which is held and is also reported on every train return as a value.", "The filter grain exponent, which is held and is also the one exponent this module exports as a declared constant.", "The attachment efficiency, which is held AND is the one calibration in this module.", "The second half of the API 421 velocity rule, which is held and is also declared as a limit."]'::jsonb, 2, 'Its value was chosen so that a cell at the module''s own defaults cuts in the range induced gas flotation is customarily credited with, and nothing here presents it as published.'),
  ('producedwater', 'advanced', 'final', null, 37, 'What does this module do in place of guessing a value it has no publication for?', '["It states the ABSENCE, which is the honest form and is also the harder one to write.", "It carries the customary value and marks it as unvalidated in the frozen constants object.", "It refuses every call that would have needed the number.", "It reports the answer with the missing number set to one, so the reader can scale it themselves."]'::jsonb, 0, 'Held means the repository carries no publication for the number, and no gate pretends to validate it.'),
  ('producedwater', 'advanced', 'final', null, 38, 'plateEfficiencyFactor is 0.7. What is it, and what kind of number is it?', '["The fraction of the plate count that is effective at the pack''s own design rate, and it is a figure derived from the geometry of the pack.", "The fraction of a plate pack''s projected area that actually settles, and it is DECLARED with no source in this repository.", "The efficiency of the pack at its own cut size, and it is an identity, since a cut size removes half the volume.", "The share of the plan area that the plates project onto, and it is a figure calibrated against the published plate pack cases."]'::jsonb, 1, 'It is one of the shape and scale constants held for literature, pinned by literal in the jest suite rather than validated.'),
  ('producedwater', 'advanced', 'final', null, 39, 'Standard gravity comes out of this module at 9.806650 m/s2. How was that figure obtained?', '["It was read off the frozen constants object, where it is declared with the rest of the fit coefficients.", "It was taken from the oracle, which types it out in full as part of the force balance it solves.", "It was fitted from the published rise rows, which straddle the creeping flow band on both sides.", "It was MEASURED out of the engine: eighteen times the viscosity times the rise velocity, over the diameter squared times the density difference."]'::jsonb, 3, 'It is a property of the planet rather than a choice this module made, and the arithmetic that recovers it is stated beside the figure.'),
  ('producedwater', 'advanced', 'final', null, 40, 'The half-area radius of a round liner comes out at 0.707106781187 of the radius. What is it, and why does the module treat it as a criterion?', '["It is the radius at which the centrifugal field equals the field at the wall, so it sets the travel.", "It is a declared constant, chosen so that the median droplet has a stated distance to cross.", "It is one over the root of two, the radius at which half the flow area lies inside, so it is where the MEDIAN droplet enters, and the module refuses an oil core wider than it.", "It is the fraction of the bore the oil core occupies, which is a declared choice in this module."]'::jsonb, 2, 'Past one over the root of two the core is OUTSIDE the half-area radius, so the median droplet starts inside the core and there is nothing for it to cross.'),
  ('producedwater', 'advanced', 'final', null, 41, 'The filter coefficient at the reported cut size, times the bed depth, comes to 0.693147180560. What does that say about how a cut size is defined here?', '["Both interception devices define the cut as the droplet where HALF the volume goes, and half survives an exponential at the log of two.", "Both interception devices define the cut at the reference droplet of 20 micron, where the coefficient is declared.", "The bed defines its cut by the depth at which the penetration reaches the declared coefficient of 3.5 per m.", "The bed defines its cut as the droplet whose filter coefficient equals the log of two, whatever the depth."]'::jsonb, 0, 'It is measured out of the bed rather than typed: the three reported quantities multiplied. A cut size is where half the volume goes.'),
  ('producedwater', 'advanced', 'final', null, 42, 'What does this module say about a discharge limit of its own?', '["That it carries one for a complete train and withholds it for a partial one.", "That it states none, and a test asserts that its declared constants carry no specification-like key at all.", "That it holds one inside the frozen constants object and then applies it only when a caller has asked for a verdict.", "That it takes the customary figure for the industry and reports the margin against it on every train return."]'::jsonb, 1, 'A specification is the caller''s own, out of the caller''s own permit or regulation. Anyone quoting a figure from the verdict block as a limit has quoted an example.');
